-- V-024 (run O1, session.sh G and J4): after 024-dle-series-games.sql
-- Read only, in a read-only transaction. Each row is: ok or KO | what | the number found. Never a name, an e-mail or a row of a person.
-- From the header of 024-dle-series-games.sql. The game rows come with L01's anime site (J4): before it the rows must be absent, after it there; off until L14 (a game
-- under its minimum stays off), and whole when on (365 days).
begin transaction read only;
select case when ok is true then 'ok' else 'KO' end, what, coalesce(got, '-') from (values
  (1, 'character_game_facts avec RLS, aucune policy', (select count(*) = 1 from pg_class c where c.oid = to_regclass('public.character_game_facts') and c.relrowsecurity and not exists (select 1 from pg_policy p where p.polrelid = c.oid)), null),
  (2, 'colonnes de character_game_facts : 6', (select count(*) = 6 from information_schema.columns where table_schema = 'public' and table_name = 'character_game_facts' and column_name in ('character_id', 'game_id', 'attrs', 'hints', 'can_be_target', 'updated_at')), null),
  (3, 'la table fermée à anon et authenticated, ouverte au service_role', (select not has_table_privilege('anon', t, 'select') and not has_table_privilege('authenticated', t, 'select') and not has_table_privilege('anon', t, 'insert') and not has_table_privilege('authenticated', t, 'insert') and has_table_privilege('service_role', t, 'select') from (values ('public.character_game_facts')) as x(t)), null),
  (4, 'les deux vues en security_invoker, fermées au navigateur', (select count(*) = 2 and bool_and(coalesce('security_invoker=true' = any (reloptions), false) and not has_table_privilege('anon', oid, 'select') and not has_table_privilege('authenticated', oid, 'select')) from pg_class where oid in (to_regclass('public.dle_src_otakudle_one_piece'), to_regclass('public.dle_src_otakudle_dragon_ball'))), null),
  (5, 'les vues gardent la règle : publié, identity_spoiler faux, série publiée', (select count(*) = 2 and bool_and(d ~ 'published' and d ~ 'identity_spoiler') from (select pg_get_viewdef(oid) as d from pg_class where oid in (to_regclass('public.dle_src_otakudle_one_piece'), to_regclass('public.dle_src_otakudle_dragon_ball'))) v), null),
  (6, 'les deux jeux : là si le site anime est là, absents avant L01', (select (select count(*) from public.dle_games where id in ('otakudle-one-piece', 'otakudle-dragon-ball')) = case when exists (select 1 from public.sites where id = 'anime') then 2 else 0 end), (select count(*)::text from public.dle_games where id in ('otakudle-one-piece', 'otakudle-dragon-ball'))),
  (7, 'éteints sans date ni banque, ou allumés par L14 avec leurs 365 jours', (select coalesce(bool_and((not g.active and g.epoch is null and not exists (select 1 from public.dle_schedule s where s.game_id = g.id)) or (g.active and g.epoch is not null and (select count(*) from public.dle_schedule s where s.game_id = g.id) = 365)), true) from public.dle_games g where g.id in ('otakudle-one-piece', 'otakudle-dragon-ball')), null),
  (8, 'colonnes : One Piece 8 et Dragon Ball 8 si les jeux sont là', (select (select count(*) from public.dle_attributes where game_id in ('otakudle-one-piece', 'otakudle-dragon-ball')) = case when exists (select 1 from public.dle_games where id = 'otakudle-one-piece') then 16 else 0 end), (select count(*)::text from public.dle_attributes where game_id in ('otakudle-one-piece', 'otakudle-dragon-ball'))),
  (9, 'Dragon Ball sans colonne de taille (décision du 2026-11-03)', (select not exists (select 1 from public.dle_attributes where game_id = 'otakudle-dragon-ball' and key = 'height_cm')), null),
  (10, 'indices : One Piece fruit du démon à 5 puis initiale à 10, Dragon Ball technique et doubleur à 5 puis initiale à 10', (select coalesce(bool_and(case g.id when 'otakudle-one-piece' then hint_keys = '{devil_fruit_name,initial}' and hint_after = '{5,10}' else hint_keys = '{signature_technique,voice_actor_ja,initial}' and hint_after = '{5,5,10}' end), true) from public.dle_games g where g.id in ('otakudle-one-piece', 'otakudle-dragon-ball')), null),
  (11, 'minimum du pool : One Piece 40, Dragon Ball 30 au départ (information, le jour J peut les baisser)', true, (select string_agg(id || ' ' || min_pool, ', ' order by id) from public.dle_games where id in ('otakudle-one-piece', 'otakudle-dragon-ball'))),
  (12, 'One Piece : personnages dans la vue (information)', true, (select count(*)::text from public.dle_src_otakudle_one_piece)),
  (13, 'Dragon Ball : personnages dans la vue (information)', true, (select count(*)::text from public.dle_src_otakudle_dragon_ball))
) as c(n, what, ok, got) order by n;
rollback;
